text:
{
 "summary": {
  "es": "G7（7か国《こく》とEU）、G20、APEC（21のエコノミー＝国《くに》や地域《ちいき》）の、なかまのつくりと、2026年《ねん》の議長国《ぎちょうこく》（会議《かいぎ》をまとめる国《くに》）のお話《はなし》です。議長国《ぎちょうこく》は、フランス・米国《べいこく》（アメリカ）・中国《ちゅうごく》です。",
  "hs": "G7（7か国とEU）、G20、APEC（21エコノミー＝国・地域）の構成と、2026年の議長国（フランス・米国・中国）。"
 },
 "blocks/0/text": {
  "es": "2026年《ねん》のG7サミットでは、どんなことが話《はな》し合《あ》われたのでしょうか？",
  "hs": "2026年のG7サミットでは、どんな議題が話し合われたのでしょうか？"
 },
 "blocks/2/text": {
  "es": "2026年《ねん》6月《がつ》のG7エビアン・サミットに、高市《たかいち》首相《しゅしょう》が出席《しゅっせき》しました。6月《がつ》15日《にち》には、夕食《ゆうしょく》をとりながらの会議《かいぎ》（ワーキングディナー）がありました。そこで、中東《ちゅうとう》、ウクライナ、インド太平洋《たいへいよう》、重要鉱物《じゅうようこうぶつ》（大切《たいせつ》な鉱物《こうぶつ》）などについて話《はな》し合《あ》いました。",
  "hs": "2026年6月のG7エビアン・サミットに高市首相が出席した。6月15日のワーキングディナー（夕食をとりながらの会議）で、中東、ウクライナ、インド太平洋、重要鉱物などについて議論した。"
 },
 "blocks/4/text": {
  "es": "2026年《ねん》8月《がつ》31日《にち》から9月《がつ》1日《ついたち》に、米国《べいこく》（アメリカ）のアシュビルで、G20財務大臣《ざいむだいじん》・中央銀行総裁会議《ちゅうおうぎんこうそうさいかいぎ》が開《ひら》かれました。日本《にほん》は、2019年《ねん》にG20の議長国《ぎちょうこく》でした。",
  "hs": "G20財務大臣・中央銀行総裁会議が、2026年8月31日〜9月1日に米国・アシュビルで開かれた。日本は2019年にG20の議長国だった。"
 }
}
